  $heading='<wpml:waypointHeadingParam><wpml:waypointHeadingMode>towardPOI</wpml:waypointHeadingMode><wpml:waypointPoiPoint>48.001,16.002,20</wpml:waypointPoiPoint><wpml:waypointHeadingPoiIndex>0</wpml:waypointHeadingPoiIndex></wpml:waypointHeadingParam>';
  $route.='<Placemark>'.$base.'<wpml:executeHeight>60</wpml:executeHeight><wpml:waypointSpeed>3</wpml:waypointSpeed>'.$heading.$action.'</Placemark>';
  $template.='<Placemark>'.$base.'<wpml:height>60</wpml:height><wpml:ellipsoidHeight>260</wpml:ellipsoidHeight><wpml:useGlobalHeight>1</wpml:useGlobalHeight>'.$heading.$action.'</Placemark>';
 }
 return ['wpmz/template.kml'=>$wrap('<wpml:droneEnumValue>99</wpml:droneEnumValue>'.($full?'<Folder><wpml:templateType>waypoint</wpml:templateType><wpml:templateId>0</wpml:templateId><wpml:globalHeight>60</wpml:globalHeight><wpml:waylineCoordinateSysParam><wpml:coordinateMode>WGS84</wpml:coordinateMode><wpml:heightMode>relativeToStartPoint</wpml:heightMode></wpml:waylineCoordinateSysParam>'.$template.'</Folder>':'')),
 'wpmz/waylines.wpml'=>$wrap('<Folder><wpml:templateId>0</wpml:templateId><wpml:waylineId>0</wpml:waylineId><wpml:executeHeightMode>relativeToStartPoint</wpml:executeHeightMode><wpml:distance>223.3</wpml:distance><wpml:duration>100</wpml:duration>'.$route.'</Folder>'), 'wpmz/res/original.bin'=>"\x00private synthetic asset\xff"];
