function zipfile(array $entries): string {$p=tempnam(sys_get_temp_dir(),'ke-test-');$z=new ZipArchive();$z->open($p,ZipArchive::OVERWRITE);foreach($entries as $n=>$v)$z->addFromString($n,$v);$z->close();return $p;}
