 foreach([true,false] as $full){$entries=fixture($full);$files[]=$p=zipfile($entries);$hash=hash_file('sha256',$p);$files[]=$out=tempnam(sys_get_temp_dir(),'ke-out-');$before=dm_ke_load($p);check(dm_ke_structure_allowed($before),'single point actions editable');
  $journal=dm_ke_edit($p,$out,[['index'=>1,'lat'=>48.0001,'lng'=>16.0011,'height'=>72]]);$d=dm_ke_load($out);check($d['points'][1]['height']===72.0&&$d['points'][1]['lat']===48.0001,'coordinates/height');check(count($journal)===1,'journal');check(hash_file('sha256',$p)===$hash,'original unchanged');
  foreach($before['marks'] as $i=>$mark){check(dm_ke_node($mark,'actionGroup')->C14N()===dm_ke_node($d['marks'][$i],'actionGroup')->C14N(),'actions preserved');check(dm_ke_node($mark,'waypointHeadingParam')->C14N()===dm_ke_node($d['marks'][$i],'waypointHeadingParam')->C14N(),'POI and heading preserved');}
  $z=new ZipArchive();$z->open($out);check($z->getFromName('wpmz/res/original.bin')===$entries['wpmz/res/original.bin'],'asset bytes preserved');if(!$full)check($z->getFromName('wpmz/template.kml')===$entries['wpmz/template.kml'],'metadata template byte preserved');$z->close();
  if($full){check(dm_ke_text($d['tm'][1],'height')==='72.000'&&dm_ke_text($d['tm'][1],'useGlobalHeight')==='0','global height override');check(dm_ke_text($d['tm'][1],'ellipsoidHeight')==='272.000','ellipsoid delta');check(dm_ke_coords($d['tm'][1])===dm_ke_coords($d['marks'][1]),'template coordinates updated');}
  dm_ke_edit($p,$out,[],[1],[['after'=>2,'lat'=>48.0002,'lng'=>16.0025,'height'=>80]]);$d=dm_ke_load($out);check(count($d['points'])===4&&$d['points'][1]['lng']===16.002&&$d['points'][2]['height']===80.0,'delete and insert order');check(!dm_ke_children($d['marks'][2],'actionGroup'),'new point has no actions');check(dm_ke_text(dm_ke_node($d['marks'][1],'actionGroup'),'actionGroupStartIndex')==='1','surviving action reference reindexed');check(dm_ke_text(dm_ke_node($d['marks'][1],'actionGroup'),'actionGroupId')==='2','action IDs preserved');
  reject(fn()=>dm_ke_edit($p,$out,[]),'no-op');reject(fn()=>dm_ke_edit($p,$out,[['index'=>0,'height'=>60]]),'unchanged value');reject(fn()=>dm_ke_edit($p,$out,[],[0,1,2]),'minimum two');reject(fn()=>dm_ke_edit($p,$out,[['index'=>1,'height'=>70]],[1]),'edit deleted point');reject(fn()=>dm_ke_edit($p,$out,[['index'=>1,'lat'=>91]]),'bad latitude');reject(fn()=>dm_ke_edit($p,$out,[['index'=>1,'other'=>3]]),'unknown field');
 }
 foreach(['duplicate','mismatch','mode','altitude','multi','template-height'] as $case){$e=fixture();if($case==='duplicate')$e['wpmz/waylines.wpml']=str_replace('<wpml:index>3','<wpml:index>2',$e['wpmz/waylines.wpml']);if($case==='mismatch')$e['wpmz/template.kml']=str_replace('16.001,48','16.009,48',$e['wpmz/template.kml']);if($case==='mode')$e['wpmz/waylines.wpml']=str_replace('relativeToStartPoint','realTimeFollowSurface',$e['wpmz/waylines.wpml']);if($case==='altitude')$e['wpmz/waylines.wpml']=str_replace('16,48</coordinates>','16,48,12</coordinates>',$e['wpmz/waylines.wpml']);if($case==='multi')$e['wpmz/waylines.wpml']=str_replace('</Document>','<Folder/></Document>',$e['wpmz/waylines.wpml']);if($case==='template-height')$e['wpmz/template.kml']=str_replace('<wpml:globalHeight>60','<wpml:globalHeight>61',$e['wpmz/template.kml']);$files[]=$p=zipfile($e);reject(fn()=>dm_ke_load($p),$case);}
 $e=array_map(fn($x)=>str_replace('relativeToStartPoint','WGS84',$x),fixture());$files[]=$p=zipfile($e);dm_ke_edit($p,$out,[['index'=>1,'height'=>310.125]]);check(dm_ke_load($out)['points'][1]['height']===310.125,'WGS84 heights');
 foreach(['video','range','unknown'] as $case){$e=fixture();$e['wpmz/waylines.wpml']=$case==='range'?str_replace('<wpml:actionGroupEndIndex>0','<wpml:actionGroupEndIndex>1',$e['wpmz/waylines.wpml']):str_replace('takePhoto',$case==='video'?'startRecord':'unknownActuator',$e['wpmz/waylines.wpml']);$files[]=$p=zipfile($e);check(!dm_ke_structure_allowed(dm_ke_load($p)),'structural guard '.$case);reject(fn()=>dm_ke_edit($p,$out,[],[1]),'deletion blocked '.$case);dm_ke_edit($p,$out,[['index'=>1,'height'=>70]]);check(dm_ke_load($out)['points'][1]['height']===70.0,'nonstructural still allowed');}
 echo "PASS: KMZ edit roundtrip, original/assets/actions/POIs, template/global/ellipsoid height, insert/delete references, validation and structural action guards\n";
}finally{foreach(array_unique($files) as $p)if(is_file($p))unlink($p);}
